// One item per city. /points is called for every city even when the grid is
// already cached: it is free (no rate limit), it returns the AUTHORITATIVE
// forecast URL rather than one we assembled by hand, and it re-heals the
// cache when NWS re-grids a location.
const cfg = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json).flat();
const cap = Number(cfg.max_cities_per_run || 0) || 0;

const out = [];
for (const c of cities) {
  if (!c || !c.city_key) continue;
  if (c.nws_supported === false) continue;      // proven non-US by an earlier run
  if (c.latitude == null || c.longitude == null) continue;

  const lat = Number(c.latitude).toFixed(4);
  const lon = Number(c.longitude).toFixed(4);
  out.push({ json: {
    city_key: c.city_key,
    grid_wfo: c.nws_grid_wfo ?? null,
    grid_x: c.nws_grid_x ?? null,
    grid_y: c.nws_grid_y ?? null,
    point_url: `https://api.weather.gov/points/${lat},${lon}`,
  }});
  if (cap && out.length >= cap) break;
}
if (out.length === 0) {
  throw new Error('No cities with coordinates. NWS forecasts are addressed by ' +
                  'lat/lon - check cities.latitude / longitude are populated.');
}
return out;

// Pair each /points response back to the city that asked for it, and take the
// hourly forecast URL NWS itself published.
const reqs = $('Build requests').all().map(i => i.json);
const pts  = $('Fetch point').all().map(i => i.json);

if (pts.length !== reqs.length) {
  throw new Error(
    `Point lookup returned ${pts.length} responses for ${reqs.length} cities. ` +
    `Rows are paired by position, so a mismatch would attribute one city's ` +
    `forecast to another. Nothing was written. This happens if a response body ` +
    `was a JSON array (n8n splits those into one item per element) - re-run, ` +
    `and if it persists set "Never Error" on Fetch point.`);
}

const now = new Date().toISOString();
const out = [], support = [];
let notUS = 0, failed = 0;

for (let i = 0; i < reqs.length; i++) {
  const req = reqs[i], p = pts[i] || {};
  const pp = p.properties || {};
  const is404 = p.status === 404 || String(p.title || '').includes('Not Found');

  if (is404) {
    notUS++;
    support.push({ city_key: req.city_key, nws_supported: false, nws_checked_at: now });
    continue;
  }
  // Prefer the URL NWS published; fall back to the cached grid if this one
  // call failed but an earlier run already resolved the location.
  let url = pp.forecastHourly || null;
  if (!url && req.grid_wfo && req.grid_x != null && req.grid_y != null) {
    url = `https://api.weather.gov/gridpoints/${req.grid_wfo}/${req.grid_x},${req.grid_y}/forecast/hourly`;
  }
  if (!url) { failed++; continue; }

  // units=si asks for Celsius. The parser still reads temperatureUnit rather
  // than trusting the request - a server that ignores the parameter would
  // otherwise silently store Fahrenheit as Celsius.
  const sep = url.includes('?') ? '&' : '?';
  out.push({ json: {
    city_key: req.city_key,
    grid_wfo: pp.gridId ?? req.grid_wfo ?? null,
    grid_x: pp.gridX ?? req.grid_x ?? null,
    grid_y: pp.gridY ?? req.grid_y ?? null,
    hourly_url: `${url}${sep}units=si`,
  }});
  if (pp.gridId) {
    support.push({
      city_key: req.city_key, nws_supported: true, nws_checked_at: now,
      nws_grid_wfo: pp.gridId, nws_grid_x: pp.gridX ?? null, nws_grid_y: pp.gridY ?? null,
    });
  }
}

if (out.length === 0) {
  throw new Error(
    `No forecast URLs resolved from ${reqs.length} cities ` +
    `(${notUS} are not US locations, ${failed} failed). If every city is ` +
    `non-US that is expected and this workflow has nothing to do.`);
}
// Carry the bookkeeping on the first item; later nodes read it by name.
out[0].json._support = support;
out[0].json._not_us = notUS;
out[0].json._failed = failed;
out[0].json._requested = reqs.length;
return out;

// Hourly periods -> one daily max per local calendar day, per city.
const cfg = $('Config').first().json;
const model = cfg.model_label || 'nws';
const horizon = Number(cfg.max_horizon_days || 7);
const [winFrom, winTo] = String(cfg.peak_window || '12-18').split('-').map(Number);

const reqs = $('Build forecast urls').all().map(i => i.json);
const res  = $('Fetch hourly forecast').all().map(i => i.json);

if (res.length !== reqs.length) {
  throw new Error(
    `Forecast fetch returned ${res.length} responses for ${reqs.length} cities. ` +
    `Rows are paired by position, so a mismatch would attribute one city's ` +
    `forecast to another. Nothing was written.`);
}

const forecasts = [];
let ok = 0, failed = 0, partial = 0;

for (let i = 0; i < reqs.length; i++) {
  const req = reqs[i], r = res[i] || {};
  const props = r.properties || {};
  const periods = Array.isArray(props.periods) ? props.periods : [];

  // A response that names a different gridpoint than we asked for means the
  // pairing slipped. Refuse rather than write one city's weather to another.
  if (props.gridId && req.grid_wfo && props.gridId !== req.grid_wfo) {
    throw new Error(
      `Forecast for grid ${props.gridId} came back where ${req.grid_wfo} ` +
      `(${req.city_key}) was expected. Responses are out of order - nothing written.`);
  }
  if (!periods.length) { failed++; continue; }

  // NWS issuance time, so re-running between issuances updates in place.
  const runAt = props.updateTime || props.generatedAt || new Date().toISOString();

  // startTime carries the gridpoint's own offset, e.g. 2026-09-03T14:00:00-04:00,
  // so slicing the date off gives the LOCAL calendar day with no tz table.
  const byDay = new Map();
  for (const p of periods) {
    if (!p || !p.startTime) continue;
    const day = String(p.startTime).slice(0, 10);
    const hour = Number(String(p.startTime).slice(11, 13));
    let t = Number(p.temperature);
    if (!Number.isFinite(t)) continue;
    if (String(p.temperatureUnit || '').toUpperCase() === 'F') t = (t - 32) * 5 / 9;
    if (!byDay.has(day)) byDay.set(day, { hours: new Set(), max: -Infinity, min: Infinity, at: null, n: 0 });
    const d = byDay.get(day);
    d.hours.add(hour);
    d.n++;
    if (t > d.max) { d.max = t; d.at = p.startTime; }
    if (t < d.min) d.min = t;
  }

  const days = [...byDay.keys()].sort();
  if (!days.length) { failed++; continue; }
  const today = days[0];                       // periods start at the current hour
  let wrote = 0;

  for (const day of days) {
    const d = byDay.get(day);
    // Skip a day whose series misses any of the peak hours: its max would be
    // below the real one, and a too-low max invents divergence out of nothing.
    let covered = true;
    for (let h = winFrom; h <= winTo; h++) if (!d.hours.has(h)) { covered = false; break; }
    if (!covered) { partial++; continue; }

    const lead = Math.round((Date.parse(day + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000);
    if (lead < 0 || lead > horizon) continue;

    forecasts.push({
      city_key: req.city_key,
      model,
      run_at: runAt,
      for_date: day,
      lead_days: lead,
      forecast_max_c: Number(d.max.toFixed(2)),
      source: 'api.weather.gov',
      variables: {
        min_c: Number(d.min.toFixed(2)),
        max_at_local: d.at,
        n_hours: d.n,
        peak_window: `${winFrom}-${winTo}`,
        grid: req.grid_wfo ? `${req.grid_wfo}/${req.grid_x},${req.grid_y}` : null,
        issued_at: runAt,
      },
    });
    wrote++;
  }
  if (wrote) ok++; else failed++;
}

return [{ json: {
  forecasts,
  support: reqs[0] && reqs[0]._support ? reqs[0]._support : [],
  n_forecasts: forecasts.length,
  cities_ok: ok, cities_failed: failed, partial_days: partial,
  requested: (reqs[0] && reqs[0]._requested) || reqs.length,
  not_us: (reqs[0] && reqs[0]._not_us) || 0,
} }];

const p = $('Build rows').first().json;
if (p.n_forecasts === 0) {
  throw new Error(
    `Parsed 0 forecast days from ${p.cities_ok + p.cities_failed} cities ` +
    `(${p.partial_days} day(s) skipped for not covering the peak window). ` +
    `Nothing written. If this ran late in the evening, today is legitimately ` +
    `incomplete - but tomorrow onwards should still be present, so 0 across ` +
    `the board means the forecast fetch failed.`);
}
return [{ json: p }];

const p = $('Build rows').first().json;
const rows = p.n_forecasts || 0;
const summary =
  `AD4 P1.3: ${rows} NWS forecast day(s) for ${p.cities_ok} cities` +
  (p.not_us ? `, ${p.not_us} not US locations` : '') +
  (p.cities_failed ? `, ${p.cities_failed} failed` : '') +
  (p.partial_days ? `, ${p.partial_days} partial day(s) skipped` : '') + '.';
const status = rows > 0 ? (p.cities_failed ? 'attention' : 'ok') : 'attention';
const detail = { cities_ok: p.cities_ok, cities_failed: p.cities_failed,
                 partial_days: p.partial_days, not_us: p.not_us,
                 requested: p.requested };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P1.3_nws_forecast', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];
